//! Raw FFI for oxgl: ANGLE (EGL/GLES), plus minimal Node-API typed-array access
//! behind the `node` feature. This is the only workspace crate allowed to
//! contain `unsafe` code; every `unsafe` block carries a `// SAFETY:` comment.
#![deny(unsafe_op_in_unsafe_fn)]

/// EGL/GLES types and constants generated by bindgen from the bundle headers.
#[allow(
    // Generated code: C naming, no docs, and casts/patterns clippy dislikes.
    non_camel_case_types,
    non_snake_case,
    non_upper_case_globals,
    missing_docs,
    unsafe_op_in_unsafe_fn,
    clippy::all,
    clippy::pedantic,
    clippy::undocumented_unsafe_blocks
)]
pub mod bindings {
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

mod calls;
mod egl;
mod framebuffers;
mod loader;
#[cfg(feature = "node")]
pub mod napi_view;
mod pointers;
mod state;
#[cfg(feature = "test-support")]
pub mod test_support;
mod textures;
mod view;

pub use egl::{
    ClientVersion, Current, Display, DisplayKind, EglError, GlContext, ReadPixels, live_contexts,
};
pub use framebuffers::ClearValues;
pub use loader::{Angle, LoadError, LoadErrorKind};
pub use pointers::{
    ActiveInfo, AttribQuery, Quad, UniformData, UniformMatrix, UniformOut, UniformVector,
};
pub use state::{PrecisionFormat, StateCall, ValueType, Values};
pub use textures::{TexImage, Upload, UploadData};
pub use view::{ByteSource, PixelDestination, ViewKind};
